def ledger(data, priority, tax_base, half_up):
    def rounded(numerator, denominator):
        if half_up:
            return (numerator + denominator // 2) // denominator
        return numerator // denominator

    cutoff = data.get("cutoff", 10**9)
    chosen = {}
    for position, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        if priority == "revision_first":
            key = (event.get("revision", 0), position)
        else:
            key = (event.get("sequence", 0), event.get("revision", 0), position)
        if event_id not in chosen or key > chosen[event_id][0]:
            chosen[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), 10000)
        base = raw if tax_base == "original" else net
        tax = rounded(base * event.get("tax_bp", 0), 10000)
        amount = net + tax
        if event.get("kind") == "refund":
            amount = -amount
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + amount
    return {"balances": balances}


def resolve(data):
    packages = data["packages"]
    names = sorted(packages, reverse=True)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    options = []
    for name in names:
        versions = [row["version"] for row in packages[name]
                    if row["version"] not in blocked.get(name, [])
                    and (name not in pins or row["version"] == pins[name])]
        options.append([None] + versions)

    best_vector = None
    best_installation = None
    for values in product(*options):
        assigned = dict(zip(names, values))
        constraints = {}
        for name, bounds in data["roots"].items():
            constraints.setdefault(name, []).append(tuple(bounds))

        graph = {}
        reached = set()
        pending = list(data["roots"])
        valid = True
        while pending and valid:
            name = pending.pop()
            version = assigned[name]
            if version is None:
                valid = False
                break
            reached.add(name)
            if name not in graph:
                row = next(row for row in packages[name]
                           if row["version"] == version)
                graph[name] = []
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature:
                        if feature not in features:
                            continue
                    other = dep["name"]
                    graph[name].append(other)
                    constraints.setdefault(other, []).append((dep["min"], dep["max"]))
                    pending.append(other)

        if not valid:
            continue
        if any(assigned[name] is None or
               any(not low <= assigned[name] <= high for low, high in ranges)
               for name, ranges in constraints.items()):
            continue
        if any(assigned[name] is not None for name in names if name not in reached):
            continue

        state = {}
        def acyclic(name):
            if state.get(name) == 1:
                return False
            if state.get(name) == 2:
                return True
            state[name] = 1
            if any(not acyclic(other) for other in graph.get(name, [])):
                return False
            state[name] = 2
            return True

        if not all(acyclic(name) for name in reached):
            continue

        vector = tuple(assigned[name] if assigned[name] is not None else -1
                       for name in names)
        if best_vector is None or vector > best_vector:
            best_vector = vector
            best_installation = {name: assigned[name] for name in names
                                 if name in reached}

    if best_installation is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_installation}


def schedule(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None

    for mask in range(1 << len(jobs)):
        selected = [jobs[i] for i in range(len(jobs)) if mask & (1 << i)]
        if len(selected) != k:
            continue
        ids = {job["id"] for job in selected}
        if ids & blocked or not mandatory <= ids:
            continue
        counts = {}
        for job in selected:
            group = job["group"]
            counts[group] = counts.get(group, 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue

        events = []
        for job in selected:
            events.append((job["start"], 1))
            events.append((job["end"], -1))
        active = 0
        feasible = True
        for _, change in sorted(events, key=lambda item: (item[0], item[1])):
            active += change
            if active > 2:
                feasible = False
                break
        if not feasible:
            continue

        value = sum(job["value"] for job in selected)
        ordered_ids = tuple(sorted(ids))
        if (best_value is None or value > best_value or
                (value == best_value and ordered_ids > best_ids)):
            best_value, best_ids = value, ordered_ids

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def routes(data):
    import heapq

    required = data.get("required", [])
    bits = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    source = data["source"]
    initial_mask = bits.get(source, 0)
    initial_state = (source, initial_mask, data["coupons"])
    distances = {initial_state: data["start"]}
    queue = [(data["start"], source, initial_mask, data["coupons"])]

    while queue:
        arrival, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if distances.get(state) != arrival:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": arrival}

        for edge in graph[node]:
            depart = max(arrival, edge["open"])
            if depart >= edge["close"]:
                continue
            choices = [(edge["duration"], remaining)]
            if remaining:
                discounted = max(1, edge["duration"] - edge.get("discount", 0))
                choices.append((discounted, remaining - 1))
            for duration, left in choices:
                when = depart + duration
                if when > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bits.get(next_node, 0)
                next_state = (next_node, next_mask, left)
                if when < distances.get(next_state, float("inf")):
                    distances[next_state] = when
                    heapq.heappush(queue, (when, next_node, next_mask, left))

    return {"arrival": None}


